            lsr.l   #4,d2
            move.l  d1,d3
            and.l   #$00f000,d3
            lsr.l   #8,d3
            or.w    d3,d2
            move.l  d1,d3
            and.l   #$0000f0,d3
            lsr.l   #4,d3
            or.w    d3,d2

            move.l  d1,d3
            and.l   #$0f0000,d3
            lsr.l   #8,d3
            move.l  d1,d0
            and.l   #$000f00,d0
            lsr.l   #4,d0
            or.w    d0,d3
            move.l  d1,d0
            and.l   #$00000f,d0
            or.w    d0,d3

            move.w  d4,custom.BPLCON3
